cd /workspace/project && python3 - <<'EOF'
import json, urllib.request, urllib.error, concurrent.futures
live=json.load(open('/tmp/nm_live.json'))
def chat(k):
    body={"model":"deepseek_v4.1_flash_1017_uncensored","messages":[{"role":"user","content":"balas satu kata: ok"}],"max_tokens":10}
    r=urllib.request.Request('https://nomask.ai/api/v1/chat/completions',data=json.dumps(body).encode(),
        headers={'Authorization':'Bearer '+k,'Content-Type':'application/json'})
    try:
        with urllib.request.urlopen(r,timeout=90) as resp:
            j=json.load(resp); return k,True,j['choices'][0]['message']['content'][:25]
    except urllib.error.HTTPError as e:
        return k,False,f'http{e.code} '+e.read()[:90].decode(errors='ignore')
    except Exception as e: return k,False,type(e).__name__
ok=0; bad=[]
with concurrent.futures.ThreadPoolExecutor(5) as ex:
    for k,s,msg in ex.map(chat,list(live)):
        if s: ok+=1
        else: bad.append((k[:22],msg))
print(f"chat OK: {ok}/{len(live)}")
for b in bad[:5]: print("  ",b)
EOF

